{
  "packet_id": "H6-T03-3",
  "claim_id": "C032",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C032.component",
    "value": "Ordinary variation may change attachment rates.",
    "scope": "A possible alternative explanation for rate changes, not an assertion that it occurred.",
    "provenance": {
      "refs": [
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly identifies ordinary variation as a possible cause of attachment-rate changes."
    }
  },
  "signal_basis": {
    "component_id": "C032.signal_basis",
    "value": "Missing-attachment frequency decreases after responsibility becomes explicit, assessed across comparable covered orders using consistent inspection intervals, with repetition across comparable observation periods if volume permits.",
    "scope": "Before-and-after attachment-rate observations; temporal association does not exclude alternative causes.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the comparison, proposed signal, repetition qualifier, and limitation on excluding alternative causes."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C032.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is SUPPORTED, not CONDITIONAL_WARRANT."
    }
  },
  "rationale": "Attachment frequencies can fluctuate through ordinary variation even across comparable observations. The described signal does not eliminate that possibility, so the narrowly stated alternative explanation is warranted.",
  "uncertainty": "The signal does not establish whether ordinary variation actually contributed or how much.",
  "anomalies": []
}
